#!/usr/bin/env bash
# Builds libbeast_cam_bridge.so = JNI bridge + libuvc + libusb (all from source,
# no proprietary binary). Usage:
#   build-native-uvc.sh <out.so> <libusb-src> <libuvc-src>
# Compilers come from $CC / $CXX (NDK clang in CI). $NATIVE_LDLIBS defaults to
# Android's liblog.
set -euo pipefail
OUT_SO="$1"; LIBUSB="$2"; LIBUVC="$3"
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
CC="${CC:?CC required}"; CXX="${CXX:?CXX required}"
WORK="$(mktemp -d)"
LDLIBS="${NATIVE_LDLIBS:--llog -ldl}"
EXTRA_INC="${NATIVE_EXTRA_INCLUDES:-}"

# libuvc_config.h normally generated by CMake (no libjpeg: we decode in Java).
mkdir -p "$WORK/gen/libuvc"
sed -e 's/@libuvc_VERSION_MAJOR@/0/g; s/@libuvc_VERSION_MINOR@/0/g' \
    -e 's/@libuvc_VERSION_PATCH@/9/g; s/@libuvc_VERSION@/0.0.9/g' \
    -e 's|#cmakedefine LIBUVC_HAS_JPEG 1|/* LIBUVC_HAS_JPEG disabled */|' \
    "$LIBUVC/include/libuvc/libuvc_config.h.in" > "$WORK/gen/libuvc/libuvc_config.h"

CFLAGS="-O2 -fPIC -pthread -fvisibility=hidden -w"
objs=()
for f in core descriptor hotplug io sync strerror os/linux_usbfs os/events_posix os/threads_posix os/linux_netlink; do
  o="$WORK/usb_$(basename "$f").o"
  $CC $CFLAGS -I"$LIBUSB/android" -I"$LIBUSB/libusb" -I"$LIBUSB/libusb/os" -c "$LIBUSB/libusb/$f.c" -o "$o"
  objs+=("$o")
done
# Packets per isochronous URB becomes a runtime variable (uvc_ppt_max, set by
# the JNI bridge) so the bridge can retry smaller URBs on Android.
mkdir -p "$WORK/src"
{ echo "extern int uvc_ppt_max;"; sed 's/packets_per_transfer > LIBUVC_PACKETS_PER_TRANSFER_MAX/packets_per_transfer > (size_t) uvc_ppt_max/; s/packets_per_transfer = LIBUVC_PACKETS_PER_TRANSFER_MAX;/packets_per_transfer = (size_t) uvc_ppt_max;/' "$LIBUVC/src/stream.c"; } > "$WORK/src/stream.c"
grep -q "uvc_ppt_max;" "$WORK/src/stream.c"
test "$(grep -c '(size_t) uvc_ppt_max' "$WORK/src/stream.c")" = 2
for f in ctrl ctrl-gen device diag frame init misc stream; do
  o="$WORK/uvc_$f.o"
  srcf="$LIBUVC/src/$f.c"; [ "$f" = stream ] && srcf="$WORK/src/stream.c"
  $CC $CFLAGS -DLIBUVC_NUM_TRANSFER_BUFS=24 -I"$WORK/gen" -I"$LIBUVC/include" -I"$LIBUVC/src" -I"$LIBUSB/libusb" -c "$srcf" -o "$o"
  objs+=("$o")
done
$CXX -std=c++17 -O2 -fPIC -shared -static-libstdc++ -Wall \
    -I"$WORK/gen" -I"$LIBUVC/include" -I"$LIBUSB/libusb" $EXTRA_INC \
    -Wl,-z,max-page-size=16384 -Wl,--exclude-libs,ALL \
    -o "$OUT_SO" "$ROOT/app/src/main/cpp/beast_cam_bridge.cpp" "${objs[@]}" $LDLIBS
rm -rf "$WORK"
echo "native bridge: $OUT_SO ($(stat -c%s "$OUT_SO") bytes)"
